/**
 * io Python↔TS 동작 일치 회귀 테스트.
 *
 * 모든 기대값은 Python 원본(src/python/ko_pii/io_, CPython 3.12.14)을 같은 픽스처에 실제로
 * 실행해 얻은 출력이다. zip/xml 픽스처는 Python zipfile 로 만든 바이트를 base64 로 박아
 * 두었다 (EOCD 엔트리 수·선언 크기·로컬 헤더 이름 등은 바이트 패치로 조작한 것).
 * 이 파일은 생성물이 아니라 손으로 고쳐도 되지만, 기대값을 바꿀 때는 반드시 Python 실측으로.
 */
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { BoundedReadError, FileReadPolicy, readTextBounded } from "../../src/io/bounded.js";
import { CsvError, readRecordsFromText } from "../../src/io/csvReader.js";
import { readRecords as dispatchReadRecords, extensionOf } from "../../src/io/dispatcher.js";
import { readText as readDocx } from "../../src/io/docx.js";
import * as ioIndex from "../../src/io/index.js";
import { normalizeForDetection } from "../../src/io/textNormalizer.js";
import { readText as readXlsx, readRecords as readXlsxRecords } from "../../src/io/xlsx.js";

const DIR = mkdtempSync(join(tmpdir(), "ko-pii-io-parity-"));

function fixture(name: string, base64: string): string {
  const path = join(DIR, name);
  writeFileSync(path, Buffer.from(base64, "base64"));
  return path;
}

type BoundedExpectation = string | { text: string; members: number; decl: number };

async function boundedOutcome(path: string, policy?: FileReadPolicy): Promise<BoundedExpectation> {
  try {
    const doc = await readTextBounded(path, policy ?? null);
    return { text: doc.text, members: doc.archiveMembers, decl: doc.declaredDecompressedBytes };
  } catch (e) {
    if (e instanceof BoundedReadError) return `REJECT:${e.code}`;
    throw e;
  }
}

